CREATE TABLE IF NOT EXISTS "stats_report_precompute_meta" (
    "key" text,
    "value" text,
    PRIMARY KEY ("key")
);

CREATE TABLE IF NOT EXISTS "stats_report_results" (
    "_pg_rowid" bigint GENERATED BY DEFAULT AS IDENTITY,
    "session_uuid" text NOT NULL,
    "category" text NOT NULL,
    "subcategory" text NOT NULL,
    "source_name" text NOT NULL,
    "location" text NOT NULL,
    "service" text NOT NULL,
    "rank" bigint NOT NULL,
    "metric_value" double precision NOT NULL,
    "metric_name" text NOT NULL,
    "export_string" text NOT NULL,
    "dominance_bitmap" bytea NOT NULL,
    "metric_inputs_hash" text NOT NULL,
    "optimization_version" bigint NOT NULL,
    "computed_at" bigint NOT NULL,
    "extras_json" text,
    PRIMARY KEY ("session_uuid", "category", "subcategory", "source_name", "location", "service")
);

CREATE TABLE IF NOT EXISTS "stats_report_runs" (
    "id" text,
    "session_uuid" text NOT NULL,
    "categories" text NOT NULL,
    "skills" text NOT NULL,
    "total_jobs" bigint NOT NULL DEFAULT 0,
    "completed_jobs" bigint NOT NULL DEFAULT 0,
    "failed_jobs" bigint NOT NULL DEFAULT 0,
    "status" text NOT NULL DEFAULT 'running',
    "notify_on_complete" bigint NOT NULL DEFAULT 0,
    "started_at" text NOT NULL,
    "completed_at" text,
    "created_at" text NOT NULL,
    "resume_count" bigint DEFAULT 0,
    "last_progress_at" text,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "stats_report_stale_scopes" (
    "session_uuid" text NOT NULL,
    "category" text NOT NULL,
    "subcategory" text NOT NULL,
    "source_name" text NOT NULL,
    "location" text NOT NULL,
    "service" text NOT NULL,
    "reason" text NOT NULL,
    "added_item_ids" bytea,
    "removed_item_ids" bytea,
    "detected_at" bigint NOT NULL,
    PRIMARY KEY ("session_uuid", "category", "subcategory", "source_name", "location", "service")
);

CREATE TABLE IF NOT EXISTS "targeted_broadcasts" (
    "id" text,
    "message" text NOT NULL,
    "session_uuids" text NOT NULL,
    "created_at" text NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
    "created_by" text NOT NULL,
    "active" smallint DEFAULT 1,
    "send_push" bigint NOT NULL DEFAULT 0,
    "push_title" text,
    "push_message" text,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "topbar_layout" (
    "session_uuid" text,
    "layout_json" text NOT NULL DEFAULT '{}',
    "updated_at" text DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
    PRIMARY KEY ("session_uuid")
);

CREATE TABLE IF NOT EXISTS "trade_blocks" (
    "blocker_uuid" text NOT NULL,
    "blocked_name" text NOT NULL,
    "created_at" double precision,
    PRIMARY KEY ("blocker_uuid", "blocked_name")
);

CREATE TABLE IF NOT EXISTS "trade_history" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "origin_site" text NOT NULL DEFAULT 'flames',
    "items_json" text NOT NULL,
    "sold_for_json" text NOT NULL,
    "party_a_name" text NOT NULL,
    "party_b_name" text NOT NULL,
    "linked_object_ids_json" text,
    "txn_id" bigint NOT NULL,
    "created_at" double precision
);

CREATE TABLE IF NOT EXISTS "trade_messages" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "origin_site" text NOT NULL DEFAULT 'flames',
    "thread_key" text NOT NULL,
    "from_name" text NOT NULL,
    "to_name" text NOT NULL,
    "from_uuid" text,
    "to_uuid" text,
    "about_object_id" text,
    "body" text NOT NULL,
    "txn_id" bigint NOT NULL,
    "read_at" double precision,
    "created_at" double precision,
    "fed_object_id" text,
    "to_trader_id" text,
    "from_trader_id" text
);

CREATE TABLE IF NOT EXISTS "traders" (
    "session_uuid" text,
    "in_game_name" text NOT NULL,
    "display_name" text NOT NULL,
    "contact_prefs_json" text NOT NULL DEFAULT '[]',
    "auto_renew" bigint NOT NULL DEFAULT 0,
    "created_at" double precision,
    "updated_at" double precision,
    "share_inventory" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("session_uuid")
);

CREATE TABLE IF NOT EXISTS "trading_meta" (
    "key" text,
    "value" text,
    PRIMARY KEY ("key")
);

CREATE TABLE IF NOT EXISTS "trading_seq" (
    "name" text,
    "value" bigint NOT NULL,
    PRIMARY KEY ("name")
);

CREATE TABLE IF NOT EXISTS "travel_config" (
    "session_uuid" text,
    "config_json" text NOT NULL DEFAULT '{}',
    "updated_at" text NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
    PRIMARY KEY ("session_uuid")
);

CREATE TABLE IF NOT EXISTS "upgrades_trackers" (
    "id" text,
    "session_uuid" text NOT NULL,
    "name" text,
    "entries_json" text NOT NULL DEFAULT '[]',
    "is_working" bigint NOT NULL DEFAULT 0,
    "created_at" text DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
    "updated_at" text DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "walkdle_item_first_seen" (
    "item_id" text,
    "first_seen" text NOT NULL,
    PRIMARY KEY ("item_id")
);

CREATE TABLE IF NOT EXISTS "wishlist_entries" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "origin_site" text NOT NULL DEFAULT 'flames',
    "trader_uuid" text NOT NULL,
    "item_slug" text NOT NULL,
    "item_type" text NOT NULL,
    "quality_rule" text NOT NULL DEFAULT 'exact',
    "quality_floor" text NOT NULL DEFAULT '',
    "max_coins" double precision,
    "trade_for_json" text,
    "notify_match" bigint NOT NULL DEFAULT 0,
    "qty" bigint NOT NULL DEFAULT 1,
    "note" text,
    "expires_at" double precision,
    "version" bigint NOT NULL DEFAULT 1,
    "txn_id" bigint NOT NULL,
    "created_at" double precision,
    "updated_at" double precision,
    "status" text NOT NULL DEFAULT 'open'
);

CREATE TABLE IF NOT EXISTS "wishlist_match_alerts" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "trader_uuid" text NOT NULL,
    "wishlist_id" bigint NOT NULL,
    "matched_object_id" text NOT NULL,
    "txn_id" bigint NOT NULL,
    "read_at" double precision,
    "created_at" double precision
);

