-- ── Weekly job-board scraper (ui/job_board_scraper.py) ──────────────────────
CREATE TABLE IF NOT EXISTS "job_board_jobs" (
    "id" bigint PRIMARY KEY,
    "week_index" integer NOT NULL,
    "board_id" text NOT NULL,
    "board_slug" text,
    "board_name" text,
    "slot" integer,
    "difficulty_id" text,
    "special_id" text,
    "bonus" smallint DEFAULT 0,
    "required_level" integer,
    "expires_at" text,
    "goals_json" text,
    "rewards_json" text,
    "first_seen_at" text DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "job_board_ingests" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "week_index" integer,
    "status" text NOT NULL DEFAULT 'running',
    "started_at" text DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
    "finished_at" text,
    "jobs_seen" integer DEFAULT 0,
    "jobs_inserted" integer DEFAULT 0,
    "jobs_skipped" integer DEFAULT 0,
    "boards_seen" integer DEFAULT 0,
    "result_status" text,
    "error" text,
    "traceback" text
);

CREATE TABLE IF NOT EXISTS "job_board_meta" (
    "key" text PRIMARY KEY,
    "value" text
);

CREATE INDEX IF NOT EXISTS idx_job_board_jobs_week ON job_board_jobs(week_index);
CREATE INDEX IF NOT EXISTS idx_job_board_jobs_board ON job_board_jobs(board_id);
CREATE INDEX IF NOT EXISTS idx_job_board_ingests_started ON job_board_ingests(started_at DESC);
CREATE INDEX IF NOT EXISTS idx_job_board_ingests_status ON job_board_ingests(status, started_at DESC);

CREATE TABLE IF NOT EXISTS "job_board_items" (
    "id" text PRIMARY KEY,
    "slug" text,
    "name" text,
    "type" text,
    "quality" text,
    "keywords_json" text,
    "is_chest" smallint DEFAULT 0,
    "fetched_at" text DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
